package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /**
     * Derives the owner's preferred contact channel at read time: {@code EMAIL} when an email is
     * present, otherwise {@code PHONE}.
     */
    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL
            : OwnerDto.ContactPreferenceEnum.PHONE;
    }

    /** Whether the owner has a non-blank email address. */
    default boolean hasEmail(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isBlank();
    }

    /**
     * Reports the owner's bulk-signup warning: {@code true} when more than 80 owners had already
     * been created on this owner's registration business day at the time it was created. Treats a
     * missing value (owners created before this rule existed) as {@code false}.
     */
    default boolean bulkSignupWarning(Owner owner) {
        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
    }

    /**
     * Derives the owner's numeric membership level from fields captured at creation: starts at 1,
     * adds 1 when an email is present, adds 1 when the owner had no namesakes at creation
     * ({@code namesakeCount == 0}), and is capped at 3. Level 4 is reserved for tenure.
     */
    default int membershipLevel(Owner owner) {
        int level = 1;
        if (hasEmail(owner)) {
            level++;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            level++;
        }
        return Math.min(level, 3);
    }

    /**
     * Derives the owner's locality (region) at read time from the city via a fixed
     * city-to-region table: Sydney->NSW, Melbourne->VIC, Brisbane->QLD. Returns the
     * canonical region string, or {@code UNKNOWN} when the city is not in the table.
     */
    default String locality(Owner owner) {
        String city = owner.getCity();
        if (city == null) {
            return "UNKNOWN";
        }
        switch (city) {
            case "Sydney":
                return "NSW";
            case "Melbourne":
                return "VIC";
            case "Brisbane":
                return "QLD";
            default:
                return "UNKNOWN";
        }
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time email handling for {@code POST /owners}. Email is optional: an absent (null or
 * blank) value is left untouched and the request proceeds. When a value is supplied it must be
 * a syntactically valid address — otherwise the request is rejected with 400 via
 * {@link InvalidEmailException}. A valid value is normalised (trimmed and lower-cased) and
 * written back onto the body in place (the {@code @Val} object is the same instance
 * {@link BuildOwner} then maps), so the lower-cased form is what gets stored and returned.
 *
 * <p>Runs after {@link NormalizeOwnerTelephone} and before {@link CheckOwnerTelephoneUnique}.
 */
public class NormalizeOwnerEmail {

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (!OwnerEmail.isPresent(email)) {
            return;
        }
        if (!OwnerEmail.isValid(email)) {
            throw new InvalidEmailException(email);
        }
        request.setEmail(OwnerEmail.normalize(email));
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Single source of truth for the owner "household" notion used by the {@code POST /owners}
 * pipeline: two owners belong to the same household when they share a last name (compared
 * case-insensitively with collapsed whitespace) and a normalised address (see
 * {@link OwnerAddress#normalize}). Centralised here (rather than inlined in
 * {@link CheckOwnerHouseholdUnique} and {@link AssignHousehold}) so the uniqueness guard and
 * the id assignment cannot silently disagree about who belongs together.
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /** Whether the create request names the same household as an existing owner. */
    static boolean matches(OwnerFieldsDto request, Owner existing) {
        return normalize(request.getLastName()).equals(normalize(existing.getLastName()))
                && OwnerAddress.normalize(request.getAddress())
                        .equals(OwnerAddress.normalize(existing.getAddress()));
    }

    /**
     * A stable identifier for the household the request names: the first 8 bytes of
     * SHA-256 over the normalised last name and address, upper-cased hex. Deterministic, so
     * every member of the same household derives the same id.
     */
    static String deriveId(OwnerFieldsDto request) {
        String key = normalize(request.getLastName()) + "\n" + OwnerAddress.normalize(request.getAddress());
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** The last-name comparison form: trimmed, internal whitespace collapsed, lower-cased. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Single source of truth for the owner telephone normalisation rule used across the
 * {@code POST /owners} pipeline: a telephone is canonicalised to E.164 form. Both
 * {@link NormalizeOwnerTelephone} (which stores the canonical value and rejects an input that
 * cannot form one) and {@link CheckOwnerTelephoneUnique} (which compares stored values) must
 * agree on this definition, so it lives here rather than being re-implemented at each site.
 *
 * <p>The rule: strip spaces, dashes and brackets; keep a leading {@code '+'} and country code
 * when present, otherwise assume country code {@code +61} and drop a single leading {@code '0'}
 * from the national digits; the result must be a {@code '+'} followed by 8 to 15 digits. So
 * {@code "0412 345 678"} canonicalises to {@code "+61412345678"} and {@code "+64 21 123 456"}
 * to {@code "+6421123456"}.
 *
 * <p>In addition, where the country code has a known fixed national-number length, the national
 * part (the digits after the country code) must have exactly that length: {@code +61} requires
 * 9 national digits and {@code +1} requires 10. A number whose national part is the wrong length
 * for its country is not a valid E.164 number here and is rejected. Country codes without a
 * listed rule keep only the general 8-to-15-digit total check.
 */
final class OwnerTelephone {

    /**
     * Country code (without the leading {@code '+'}) to its required national-number length.
     * Ordered longest-prefix-first so a number is matched against {@code 61} before {@code 1}.
     */
    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();

    static {
        NATIONAL_LENGTHS.put("61", 9);
        NATIONAL_LENGTHS.put("1", 10);
    }

    private OwnerTelephone() {
    }

    /**
     * Canonicalise {@code telephone} to E.164 form, or return {@code null} when it cannot form a
     * valid E.164 number (null/blank input, a non-digit left after stripping separators, fewer
     * than 8 or more than 15 digits after the {@code '+'}, or a national part whose length is
     * wrong for a country code with a known fixed length — {@code +61} => 9, {@code +1} => 10).
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        // Strip spaces, dashes and brackets, leaving an optional leading '+' and the digits.
        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Leading '+' and country code present: keep as-is.
            digits = cleaned.substring(1);
        } else {
            // No country code: assume +61 and drop a single leading '0' from the national digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return null;
        }
        // Enforce the per-country national-number length where one is known.
        for (Map.Entry<String, Integer> rule : NATIONAL_LENGTHS.entrySet()) {
            String countryCode = rule.getKey();
            if (digits.startsWith(countryCode)) {
                int nationalLength = digits.length() - countryCode.length();
                if (nationalLength != rule.getValue()) {
                    return null;
                }
                break;
            }
        }
        return "+" + digits;
    }
}

